import pdfplumber
import pubchempy as pcp
from rdkit import Chem, DataStructs
from rdkit.Chem import AllChem
import os

def get_smiles(name):
    try:
        results = pcp.get_compounds(name, 'name')
        if results:
            return results[0].canonical_smiles
    except Exception:
        pass
    return None

def topk_tanimoto_similarity_molecules(target_molecule_name, molecule_pool_filepath, top_k):
    # 1. Extract names from PDF
    names = []
    if not os.path.exists(molecule_pool_filepath):
        return []

    with pdfplumber.open(molecule_pool_filepath) as pdf:
        for page in pdf.pages:
            text = page.extract_text()
            if text:
                # Assuming one name per line based on the observation
                page_names = [line.strip() for line in text.split('\n') if line.strip()]
                names.extend(page_names)

    if not names:
        return []

    # 2. Get target SMILES
    target_smiles = get_smiles(target_molecule_name)
    if not target_smiles:
        return []

    target_mol = Chem.MolFromSmiles(target_smiles)
    if not target_mol:
        return []
    target_fp = AllChem.GetMorganFingerprintAsBitVect(target_mol, 2, useChirality=True)

    # 3. Get pool SMILES and compute similarities
    results = []
    # To avoid repeated API calls for the same name if it appears multiple times (unlikely here but good practice)
    name_to_fp = {}

    for name in names:
        if name not in name_to_fp:
            smiles = get_smiles(name)
            if smiles:
                mol = Chem.MolFromSmiles(smiles)
                if mol:
                    fp = AllChem.GetMorganFingerprintAsBitVect(mol, 2, useChirality=True)
                    name_to_fp[name] = fp
                else:
                    name_to_fp[name] = None
            else:
                name_to_fp[name] = None

        fp = name_to_fp[name]
        if fp:
            similarity = DataStructs.TanimotoSimilarity(target_fp, fp)
            results.append((name, similarity))

    # 4. Sort results
    # descending order of similarity, with alphabetical ordering when ties happen
    results.sort(key=lambda x: (-x[1], x[0]))

    return results[:top_k]

if __name__ == "__main__":
    # Example usage or test can go here if needed
    # For now, just providing the function as requested.
    pass

